And the LRUCache:

public class LRUCache {
    private static final int DEFAULT_CAPACITY = 1;

    private final Map<Object, Node> map;
    private Node head;
    private Node tail;
    private int size;

    public LRUCache(int capacity) {
        this.capacity = capacity;
        this.map = new HashMap<>();
        this.size = 0;
        this.head = null;
        this.tail = null;
    }

    // Put method
    public void put(Object key, Object value) {
        if (map.containsKey(key)) {
            // Move the node to the front
            Node node = map.get(key);
            if (node == head) {
                return; // already at front
            }

            // Remove the node from its current position
            Node prev = node.prev;
            Node next = node.next;

            if (prev != null) {
                prev.next = next;
            }
            if (next != null) {
                next.prev = prev;
            }

            // Add to front
            if (head == null) {
                // The cache was empty before adding this node
                head = node;
                tail = node;
            } else {
                node.prev = null;
                node.next = head;
                head.prev = node;
                head = node;
            }
        } else {
            // Create new node
            Node node = new Node(key, value);
            // Add to front
            if (head == null) {
                head = node;
                tail = node;
            } else {
                node.prev = null;
                node.next = head;
                head.prev = node;
                head = node;
            }
            map.put(key, node);
            size++;
            if (size > capacity) {
                // Evict the tail
                Object oldestKey = tail.key;
                map.remove(oldestKey);
                if (tail.prev != null) {
                    tail.prev.next = null;
                    tail = tail.prev;
                } else {
                    head = null; // cache is now empty
                }
                size--;
            }
        }
    }

    // Get method
    public Object get(Object key) {
        if (!map.containsKey(key)) {
            return -1;
        }
        Node node = map.get(key);
        // Move to front
        if (node != head) {
            Node prev = node.prev;
            Node next = node.next;

            if (prev != null) {
                prev.next = next;
            }
            if (next != null) {
                next.prev = prev;
            }
            node.prev = null;
            node.next = head;
            head.prev = node;
            head = node;
        }
        return node.value;
    }

    // Maybe add a toString method for testing
    public String toString() {
        if (head == null) {
            return "Empty";
        }
        StringBuilder sb = new StringBuilder();
        Node current = head;
        do {
            sb.append(current);
            current = current.next;
        } while (current != null);
        return sb.toString();
    }
}

