public class LRUCache<T, V> {
    private static final Map<T, Node> map = new HashMap<>();
    private Node head = null;
    private Node tail = null;
    private int size = 0;
    private int capacity = 0;

    public LRUCache(int capacity) {
        this.capacity = capacity;
    }

    public void put(T key, V value) {
        if (map.containsKey(key)) {
            // Remove the node from the linked list
            Node existingNode = map.get(key);
            if (existingNode != head) {
                // Remove from linked list
                if (existingNode.prev != null) {
                    existingNode.prev.next = existingNode.next;
                } else {
                    head = existingNode.next;
                }
                if (existingNode.next != null) {
                    existingNode.next.prev = existingNode.prev;
                } else {
                    tail = existingNode.prev;
                }
            }
            // Remove from map
            map.remove(key);
            // Add to the end of the linked list
            Node newNode = new Node(key, value);
            tail.next = newNode;
            newNode.prev = tail;
            tail = newNode;
        } else {
            // Need to add new node
            Node newNode = new Node(key, value);
            map.put(key, newNode);
            if (size < capacity) {
                // Add to the end
                if (head == null) {
                    head = newNode;
                    tail = newNode;
                } else {
                    tail.next = newNode;
                    newNode.prev = tail;
                    tail = newNode;
                }
                size++;
            } else {
                // Evict the head node
                Node evictedNode = head;
                if (evictedNode.prev != null) {
                    evictedNode.prev.next = tail;
                } else {
                    tail = evictedNode.prev;
                }
                if (evictedNode.next != null) {
                    evictedNode.next.prev = tail;
                } else {
                    head = evictedNode.next;
                }
                // Remove from map
                map.remove(evictedNode.key);
                // Add new node to the end
                tail.next = newNode;
                newNode.prev = tail;
                tail = newNode;
                size++;
            }
        }
    }

    public V get(T key) {
        if (map.containsKey(key)) {
            Node node = map.get(key);
            // Move to the end of the linked list
            if (node != head) {
                Node nextNode = node.next;
                if (nextNode != null) {
                    node.next = nextNode.next;
                } else {
                    // If it's the last node, set tail to null
                    tail = node.prev;
                }
                if (node.prev != null) {
                    node.prev.next = nextNode;
                } else {
                    head = nextNode;
                }
                tail.next = node;
                node.prev = tail;
            }
            return node.value;
        } else {
            return null; // Or -1 depending on requirement
        }
    }

    public void remove(T key) {
        if (map.containsKey(key)) {
            Node node = map.get(key);
            if (node == head) {
                head = node.next;
                if (head != null) {
                    head.prev = null;
                } else {
                    tail = null;
                }
            } else if (node == tail) {
                tail = node.prev;
                if (tail != null) {
                    tail.next = null;
                } else {
                    head = null;
                }
            }
            map.remove(key);
        }
    }

    // Maybe add toString or other helper methods for testing
}

