public class LRUCache {
    private static final int MAX_SIZE = Integer.MAX_VALUE; // Or a specific value set in constructor

    private Node head;
    private Node tail;
    private Map<Object, Node> map;

    public LRUCache(int maxSize) {
        this.maxSize = maxSize;
        this.head = null;
        this.tail = null;
        this.map = new HashMap<>();
    }

    // Other methods: put, get, clear, size

    public void put(Object key, Object value) {
        if (map.containsKey(key)) {
            // Node exists, move to front
            Node node = map.get(key);
            if (node == head) {
                // Already at front, do nothing
            } else {
                // Remove from current position
                Node prev = node.prev;
                Node next = node.next;
                if (prev != null) {
                    prev.next = next;
                }
                if (next != null) {
                    next.prev = prev;
                }
                if (node == tail) {
                    // If it's the tail, after removal, tail becomes next
                    tail = next;
                }
                node.prev = null;
                node.next = null;
                head.next = node;
                tail.prev = node;
                head = node;
            }
        } else {
            // Node does not exist, create new node
            Node node = new Node(key, value);
            // Add to the end
            if (head == null) {
                head = node;
                tail = node;
            } else {
                tail.next = node;
                node.prev = tail;
                tail = node;
            }
            map.put(key, node);
            if (maxSize != Integer.MAX_VALUE && map.size() > maxSize) {
                // Evict the tail
                Node evictNode = tail;
                if (evictNode.prev != null) {
                    evictNode.prev.next = null;
                }
                tail = evictNode.prev;
                if (evictNode.prev != null) {
                    tail.next = evictNode;
                }
                map.remove(evictNode.key);
            }
        }
    }

    public Object get(Object key) {
        if (map.containsKey(key)) {
            Node node = map.get(key);
            // Move to front
            if (node != head) {
                Node prev = node.prev;
                Node next = node.next;
                if (prev != null) {
                    prev.next = next;
                }
                if (next != null) {
                    next.prev = prev;
                }
                head.next = node;
                tail.prev = node;
                node.prev = null;
                node.next = null;
            }
            return node.value;
        } else {
            return -1;
        }
    }

    public void clear() {
        if (head != null) {
            while (head != null) {
                Node node = head;
                if (node.prev != null) {
                    node.prev.next = null;
                }
                node.next = null;
                map.remove(node.key);
                head = node.next;
            }
        }
    }

    public int size() {
        return map.size();
    }
}

