Here's a C++ program that prints a triangle of stars based on the user's input:

```cpp
#include <iostream>
using namespace std;

int main() {
    int n;
    cout << "Enter the number of lines: ";
    cin >> n;

    if (n <= 0) {
        cout << "Error: Number must be positive." << endl;
        return 0;
    }

    for (int line = 1; line <= n; ++line) {
        string spaces(n - line, ' ');
        cout << spaces << string(line, '*') << endl;
    }

    return 0;
}
