        .form-group {
            margin-bottom: 15px;
        }

        label {
            display: block;
            margin-bottom: 5px;
            font-weight: bold;
        }

        input[type="email"] {
            width: 100%;
            padding: 8px;
            border: 1px solid #ddd;
            border-radius: 4px;
            box-sizing: border-box;
        }

        input[type="password"] {
            width: 100%;
            padding: 8px;
            border: 1px solid #ddd;
            border-radius: 4px;
            box-sizing: border-box;
        }

        .remember-me {
            margin-top: 15px;
        }

        .remember-me input {
            margin-right: 5px;
        }

        .signup {
            margin-top: 20px;
            display: none;
        }

        .signup-label {
            display: none;
        }

        input[type="submit"] {
            width: 100%;
            padding: 10px;
            background-color: #4CAF50;
            color: white;
            border: none;
            border-radius: 4px;
        }

        input[type="submit"]:hover {
            background-color: #45a049;
        }

        #remember-me {
            margin-top: 0;
        }

        .success-message {
            display: none;
            margin-top: 20px;
            text-align: center;
            color: #4CAF50;
        }
    </style>
</head>
<body>
    <div class="container">
        <h2>Login/Register</h2>
        <form id="loginForm">
            <div class="form-group">
                <label for="email">Email</label>
                <input type="email" id="email" name="email" required>
            </div>
            <div class="form-group">
                <label for="password">Password</label>
                <input type="password" id="password" name="password" required>
            </div>
            <div class="remember-me">
                <input type="checkbox" id="remember-me" name="remember-me">
                <label class="remember-me-label" for="remember-me">Remember me</label>
            </div>
            <div class="signup">
                <label class="signup-label" for="signup">Sign Up</label>
                <input type="checkbox" id="signup" name="signup" required>
            </div>
            <button type="submit" class="success-message">Login</button>
        </form>
    </div>

    <div class="success-message">
        <h3>Success!</h3>
        <p>You have been successfully logged in!</p>
        <br>
        <p>Don't have an account? <a href="#">Sign up here</a></p>
    </div>

    <script>
        const loginButton = document.querySelector('.success-message');
        loginButton.addEventListener('click', function() {
            // Add your login logic here
            alert('Login attempt detected');
            document.querySelector('.success-message').style.display = 'none';
        });

        const rememberMeCheckbox = document.getElementById('remember-me');
        const signupCheckbox = document.getElementById('signup');

        rememberMeCheckbox.addEventListener('change', function() {
            const email = document.getElementById('email').value;
            if (!email) {
                alert('Please enter your email');
                return;
            }

            const remember = this.checked;
            const signup = document.getElementById('signup').value;

            if (remember) {
                // Add your remember me logic here
                alert('Remember me detected');
            } else if (signup) {
                document.getElementById('remember-me').style.display = 'none';
                document.getElementById('signup').style.display = 'none';
                // Add your signup logic here
                alert('Sign up attempt detected');
            }
        });

        // Submit button functionality
        loginButton.addEventListener('click', function() {
            // Add your login logic here
            alert('Login attempt detected');
            document.querySelector('.success-message').style.display = 'none';
        });

        // Simulate API call
        function showSuccess(message) {
            alert(message);
            document.querySelector('.success-message').style.display = 'none';
        }

        // Login example
        function loginUser(email, password) {
            if (!email) {
                alert('Please enter your email');
                return false;
            }

            if (!password) {
                alert('Please enter your password');
                return false;
            }

            // Add your login logic here
            setTimeout(showSuccess, 2000, 'Login successful!');
            return true;
        }

        // Signup example
        function createUser(email, password) {
            // Add your signup logic here
            setTimeout(showSuccess, 2000, 'Account created successfully!');
            return true;
        }
    </script>
</body>
</html>
