        const emailInput = document.getElementById('email');
        const passwordInput = document.getElementById('password');
        const optionSelect = document.getElementById('option');
        const signupInput = document.getElementById('signup');

        const options = ['remember', 'Forgot'];
        let email = '';
        let password = '';

        form.addEventListener('submit', function(e) {
            e.preventDefault();

            // Get form values
            email = emailInput.value;
            password = passwordInput.value;
            const rememberMe = optionSelect.value;
            const isSignUp = signupInput.value.trim() !== '';

            // Basic form validation
            if (email === '' || password === '') {
                alert('Please fill in all fields');
                return;
            }

            // Here you would typically send the form to a server
            // For this example, we'll just log to the console
            console.log('Login attempt:', {
                email: email,
                password: password,
                rememberMe: rememberMe,
                isSignUp: isSignUp
            });

            // You can create an authentication system here
            // Example: database query or API call
        });

        optionSelect.addEventListener('change', function(e) {
            const value = this.value;
            if (value === 'Remember') {
                document.querySelector('#option').disabled = false;
            } else {
                document.querySelector('#option').disabled = true;
            }
        });

        signupInput.addEventListener('input', function() {
            if (this.value.trim() === '') {
                alert('Please enter a name');
            } else {
                document.getElementById('signup').disabled = false;
            }
        });

        // Example error handling
        function showError(message) {
            alert(message);
        }

        // Example password reset link
        document.querySelector('#option').addEventListener('click', function() {
            alert('Password reset page will open');
        });
    </script>
</body>
</html>
